{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "as",
      "type": "LinkComponentType",
      "description": "Custom component to render instead of <a>"
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible label (aria-label). Only use when children are not self-descriptive (e.g. icon-only links). Omit for text links; the link text is the accessible name."
    },
    {
      "name": "href",
      "type": "string",
      "description": "Link destination URL. Astryx-owned links and clickable surfaces block javascript:, vbscript:, and data:text/html after control-character removal, outer-whitespace trimming, and case-insensitive scheme inspection. The same rule covers native anchors, custom routers, Markdown links, and every activation method. Relative paths, fragments, protocol-relative URLs, HTTP(S), mailto, tel, safe custom schemes, and accepted downloads keep their existing behavior. A rejected destination renders inertly without invoking a custom router. There is no bypass prop; exceptional behavior requires caller-owned custom rendering outside this guarantee. Images and other resource URLs have separate policies."
    },
    {
      "name": "hasUnderline",
      "type": "boolean",
      "description": "Always show underline",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables the link",
      "default": "false"
    },
    {
      "name": "isExternalLink",
      "type": "boolean",
      "description": "Opens in new tab with external icon and safe rel tokens",
      "default": "false"
    },
    {
      "name": "newTabLabel",
      "type": "string",
      "description": "Screen-reader text announcing that an external link opens in a new tab. Override for localization.",
      "default": "'(opens in new tab)'"
    },
    {
      "name": "target",
      "type": "string",
      "description": "Where to open linked document. target=\"_blank\" automatically adds noopener noreferrer."
    },
    {
      "name": "rel",
      "type": "string",
      "description": "Link relationship tokens. noopener noreferrer are merged automatically for target=\"_blank\"."
    },
    {
      "name": "download",
      "type": "string | boolean",
      "description": "Causes the browser to download the linked URL. A string specifies the suggested filename."
    },
    {
      "name": "referrerPolicy",
      "type": "HTMLAttributeReferrerPolicy",
      "description": "Referrer policy for the link."
    },
    {
      "name": "onClick",
      "type": "MouseEventHandler",
      "description": "Click event handler"
    },
    {
      "name": "tooltip",
      "type": "string",
      "description": "Tooltip text displayed on hover"
    },
    {
      "name": "isStandalone",
      "type": "boolean",
      "description": "Applies base font sizing",
      "default": "false"
    },
    {
      "name": "size",
      "type": "'4xs' | '3xs' | '2xs' | 'xsm' | 'sm' | 'base' | 'lg' | 'xl' | '2xl' | '3xl' | '4xl'",
      "description": "Explicit font size override forwarded to Text."
    },
    {
      "name": "weight",
      "type": "'normal' | 'medium' | 'semibold' | 'bold'",
      "description": "Font weight override forwarded to Text."
    },
    {
      "name": "color",
      "type": "'primary' | 'secondary' | 'disabled' | 'placeholder' | 'accent' | 'inherit'",
      "description": "Text color forwarded to Text.",
      "default": "'accent'"
    },
    {
      "name": "display",
      "type": "'inline' | 'block'",
      "description": "Display type for Text.",
      "default": "'inline'"
    },
    {
      "name": "maxLines",
      "type": "number",
      "description": "Maximum lines before truncation.",
      "default": "0"
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Link content",
      "required": true
    },
    {
      "name": "component",
      "type": "LinkComponentType",
      "description": "Component to use for all link elements. It receives accepted `href` and `to` values under the shared navigation rule described on the Link `href` prop. Supported structured destinations, including their `protocol`, are checked without changing object identity. If either supplied destination is rejected, Astryx renders inert content without invoking this component; it does not pass undefined or fall back to the other destination.",
      "required": true
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Subtree",
      "required": true
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
